//<fix start>
    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        // Parse the generated SQL into components, sort the order-sensitive parts,
        // and reconstruct a canonical string for comparison. This preserves exact
        // content checks while making the test immune to implementation-dependent
        // ordering of columns and <if> blocks.
        Pattern sqlPattern = Pattern.compile(
                "^SELECT ([^ ]+(?:,[^ ]+)*)  FROM ([^ ]+) <where>(.*)</where>$",
                Pattern.DOTALL);
        Matcher sqlMatcher = sqlPattern.matcher(sql);
        Assert.assertTrue("SQL should match SELECT/FROM/WHERE structure: " + sql, sqlMatcher.matches());

        String actualColumns = sqlMatcher.group(1);
        String actualTable = sqlMatcher.group(2);
        String actualWhere = sqlMatcher.group(3);

        // Split, sort, and rejoin columns.
        List<String> actualColumnList = new ArrayList<String>(Arrays.asList(actualColumns.split(",")));
        Collections.sort(actualColumnList);
        String sortedActualColumns = join(actualColumnList, ",");

        // Extract all <if> blocks, sort them, and rejoin.
        List<String> ifBlocks = new ArrayList<String>();
        Matcher ifMatcher = Pattern.compile("<if test=\"(.*?)\">(.*?)</if>", Pattern.DOTALL).matcher(actualWhere);
        while (ifMatcher.find()) {
            ifBlocks.add(ifMatcher.group(0));
        }
        Assert.assertEquals("Unexpected number of SQL <if> blocks", 4, ifBlocks.size());

        // Verify that there is no extra content between if blocks.
        StringBuilder rawWhereBuilder = new StringBuilder();
        for (String ifBlock : ifBlocks) {
            rawWhereBuilder.append(ifBlock);
        }
        Assert.assertEquals("Unexpected content between SQL <if> blocks", rawWhereBuilder.toString(), actualWhere);

        Collections.sort(ifBlocks);
        String sortedIfBlocks = join(ifBlocks, "");

        // Build expected components in the same canonical (sorted) form.
        String expectedSortedColumns = "address,id,state,user_name";
        List<String> expectedIfBlocks = new ArrayList<String>();
        expectedIfBlocks.add("<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>");
        expectedIfBlocks.add("<if test=\"id != null\"> AND id = #{id}</if>");
        expectedIfBlocks.add("<if test=\"state != null\"> AND state = #{state}</if>");
        expectedIfBlocks.add("<if test=\"userName != null\"> AND user_name = #{userName}</if>");
        Collections.sort(expectedIfBlocks);
        String expectedSortedIfBlocks = join(expectedIfBlocks, "");

        // Reconstruct canonical SQL and compare exactly.
        String canonicalActualSql = "SELECT " + sortedActualColumns + "  FROM " + actualTable + " <where>" + sortedIfBlocks + "</where>";
        String canonicalExpectedSql = "SELECT " + expectedSortedColumns + "  FROM user <where>" + expectedSortedIfBlocks + "</where>";
        Assert.assertEquals("Canonical SQL mismatch", canonicalExpectedSql, canonicalActualSql);

        // Result mappings: sort by column name to eliminate order dependency,
        // then assert every mapping exactly as before.
        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();
        Assert.assertEquals(4, resultMappings.size());

        List<ResultMapping> sortedMappings = new ArrayList<ResultMapping>(resultMappings);
        Collections.sort(sortedMappings, new java.util.Comparator<ResultMapping>() {
            @Override
            public int compare(ResultMapping o1, ResultMapping o2) {
                return o1.getColumn().compareTo(o2.getColumn());
            }
        });

        // After sorting, the order is: address, id, state, user_name (alphabetical).
        final ResultMapping addressMapping = sortedMappings.get(0);
        final ResultMapping idMapping = sortedMappings.get(1);
        final ResultMapping stateMapping = sortedMappings.get(2);
        final ResultMapping userNameMapping = sortedMappings.get(3);

        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());

        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());

        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
        Assert.assertEquals(EnumTypeHandler.class, stateMapping.getTypeHandler().getClass());
    }

    // Helper method to join a list with a delimiter (avoids external dependency).
    private static String join(List<String> list, String delimiter) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) sb.append(delimiter);
            sb.append(list.get(i));
        }
        return sb.toString();
    }
