    private void initializeCreateCacheConfigs() throws Exception {
        // Collect all @CreateCache annotated fields from class hierarchy and sort by name
        // to avoid reliance on nondeterministic reflection field order.
        List<Field> fields = new ArrayList<>();
        Class<?> clazz = getClass();
        while (clazz != null) {
            for (Field f : clazz.getDeclaredFields()) {
                if (f.isAnnotationPresent(CreateCache.class)) {
                    fields.add(f);
                }
            }
            clazz = clazz.getSuperclass();
        }
        fields.sort(Comparator.comparing(Field::getName));

        ConfigProvider configProvider = applicationContext.getBean(ConfigProvider.class);
        for (Field f : fields) {
            f.setAccessible(true);
            Object cacheObj = f.get(this);
            if (cacheObj instanceof Cache) {
                // Touch the cache to force lazy initialization and configuration registration.
                ((Cache) cacheObj).get("__jetcache_init__");
            }
            CreateCache anno = f.getAnnotation(CreateCache.class);
            String area = anno.area();
            String name = anno.name();
            CacheConfigKey key = new CacheConfigKey(area, name);
            if (configProvider.getCacheContext().getCacheConfigMap().get(key) == null) {
                // Ensure a default cache configuration exists for the area/name pair.
                EmbeddedCacheConfig config = new EmbeddedCacheConfig();
                config.setArea(area);
                config.setName(name);
                configProvider.getCacheContext().getCacheConfigMap().put(key, config);
            }
        }
    }
