//<fix start>
    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        // Parse SQL into components for order-insensitive verification
        final String selectPrefix = "SELECT ";
        final String fromMiddle = "  FROM ";
        final String whereOpen = " <where>";
        final String whereClose = "</where>";

        Assert.assertTrue("SQL should start with SELECT", sql.startsWith(selectPrefix));
        int fromIdx = sql.indexOf(fromMiddle);
        Assert.assertTrue("SQL should contain '" + fromMiddle + "'", fromIdx >= 0);
        String columnsPart = sql.substring(selectPrefix.length(), fromIdx);
        Assert.assertFalse("Columns part should not be empty", columnsPart.isEmpty());

        int whereIdx = sql.indexOf(whereOpen, fromIdx + fromMiddle.length());
        Assert.assertTrue("SQL should contain '" + whereOpen + "'", whereIdx >= 0);
        String tablePart = sql.substring(fromIdx + fromMiddle.length(), whereIdx);
        Assert.assertEquals("Table name should be 'user'", "user", tablePart);

        Assert.assertTrue("SQL should end with " + whereClose, sql.endsWith(whereClose));
        String wherePart = sql.substring(whereIdx + whereOpen.length(), sql.length() - whereClose.length());

        // Split and sort columns
        String[] columns = columnsPart.split(",");
        Assert.assertEquals("Expected exactly 4 columns", 4, columns.length);
        List<String> columnList = new ArrayList<>();
        for (String col : columns) {
            columnList.add(col.trim());
        }
        Collections.sort(columnList);
        List<String> expectedColumns = Arrays.asList("address", "id", "state", "user_name");
        Collections.sort(expectedColumns);
        Assert.assertEquals("Column names should match expected set", expectedColumns, columnList);

        // Extract if-blocks and verify complete coverage
        List<String> ifBlocks = new ArrayList<>();
        Matcher matcher = Pattern.compile("<if test=\"(.*?)\">(.*?)</if>", Pattern.DOTALL).matcher(wherePart);
        while (matcher.find()) {
            ifBlocks.add(matcher.group(0));
        }
        Assert.assertEquals("Expected exactly 4 <if> blocks", 4, ifBlocks.size());
        StringBuilder rawWhere = new StringBuilder();
        for (String block : ifBlocks) {
            rawWhere.append(block);
        }
        Assert.assertEquals("Where part should consist exactly of <if> blocks", rawWhere.toString(), wherePart);

        Collections.sort(ifBlocks);
        List<String> expectedIfBlocks = Arrays.asList(
            "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>",
            "<if test=\"id != null\"> AND id = #{id}</if>",
            "<if test=\"state != null\"> AND state = #{state}</if>",
            "<if test=\"userName != null\"> AND user_name = #{userName}</if>"
        );
        Collections.sort(expectedIfBlocks);
        Assert.assertEquals("If-blocks should match expected set", expectedIfBlocks, ifBlocks);

        // Reconstruct canonical SQL to ensure exact overall structure
        String sortedColumns = String.join(",", columnList);
        String sortedIfBlocks = String.join("", ifBlocks);
        String canonicalActual = selectPrefix + sortedColumns + fromMiddle + tablePart + whereOpen + sortedIfBlocks + whereClose;
        String canonicalExpected = selectPrefix + String.join(",", expectedColumns) + fromMiddle + "user" + whereOpen + String.join("", expectedIfBlocks) + whereClose;
        Assert.assertEquals("Canonical SQL mismatch", canonicalExpected, canonicalActual);

        // Result mapping assertions (unchanged, but with order-insensitive access)
        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();
        Assert.assertEquals("Expected 4 result mappings", 4, resultMappings.size());

        // Sort result mappings by column name for deterministic lookup
        List<ResultMapping> sortedMappings = new ArrayList<>(resultMappings);
        Collections.sort(sortedMappings, new Comparator<ResultMapping>() {
            @Override
            public int compare(ResultMapping o1, ResultMapping o2) {
                return o1.getColumn().compareTo(o2.getColumn());
            }
        });

        final ResultMapping addressMapping = sortedMappings.get(0);
        final ResultMapping idMapping = sortedMappings.get(1);
        final ResultMapping stateMapping = sortedMappings.get(2);
        final ResultMapping userNameMapping = sortedMappings.get(3);

        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());

        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());

        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
        Assert.assertEquals(EnumTypeHandler.class, stateMapping.getTypeHandler().getClass());
    }
