    @Test
    public void testLogger() throws IOException {
        // Clean up any pollution from other tests that may have changed slf4j-simple log level
        // or cached logger instances. This must happen before any logging or logger creation.
        resetSlf4jSimpleLoggerConfiguration();

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        PrintStream ps = new PrintStream(baos, true, "UTF-8");
        PrintStream old = System.err;
        System.setErr(ps);

        XRLog.setLoggerImpl(new Slf4jLogger());
        runWithLogOutput();

        ps.flush();
        String log = baos.toString("UTF-8");

        old.println(log);
        System.setErr(old);

        Assert.assertThat(log, containsString("] [INFO]"));
        Assert.assertThat(log, containsString("] [WARN]"));
    }

    private void resetSlf4jSimpleLoggerConfiguration() {
        // Remove any previously set default log level so that the SLF4J default (INFO) is used.
        System.clearProperty("org.slf4j.simpleLogger.defaultLogLevel");

        try {
            // Reset the static configuration of org.slf4j.impl.SimpleLogger.
            Class<?> simpleLoggerClass = Class.forName("org.slf4j.impl.SimpleLogger");
            Field initializedField = simpleLoggerClass.getDeclaredField("INITIALIZED");
            initializedField.setAccessible(true);
            initializedField.setBoolean(null, false);

            Field propsField = simpleLoggerClass.getDeclaredField("SIMPLE_LOGGER_PROPS");
            propsField.setAccessible(true);
            java.util.Properties props = (java.util.Properties) propsField.get(null);
            props.clear();

            // Force re-initialization of the simple logger configuration.
            Method lazyInit = simpleLoggerClass.getDeclaredMethod("lazyInit");
            lazyInit.setAccessible(true);
            lazyInit.invoke(null);

            // Clear the logger cache so that new logger instances are created with the
            // freshly loaded configuration instead of reusing polluted cached instances.
            Object factory = org.slf4j.LoggerFactory.getILoggerFactory();
            Field loggerMapField = factory.getClass().getDeclaredField("loggerMap");
            loggerMapField.setAccessible(true);
            Map<?, ?> loggerMap = (Map<?, ?>) loggerMapField.get(factory);
            loggerMap.clear();
        } catch (Exception e) {
            throw new RuntimeException("Failed to reset slf4j-simple logger configuration", e);
        }
    }
