    @Test
    public void testEquals2Annotations()
    {
        Annotation[] qualifiersA = Arrays.copyOf(a12, a12.length);
        Annotation[] qualifiersB = Arrays.copyOf(a12, a12.length);

        Comparator<Annotation> comparator = (left, right) -> {
            if (left instanceof AnnotationWithBindingMember && right instanceof AnnotationWithBindingMember)
            {
                AnnotationWithBindingMember leftBinding = (AnnotationWithBindingMember) left;
                AnnotationWithBindingMember rightBinding = (AnnotationWithBindingMember) right;
                int valueComparison = leftBinding.value().compareTo(rightBinding.value());
                if (valueComparison != 0)
                {
                    return valueComparison;
                }
                return Integer.compare(leftBinding.number(), rightBinding.number());
            }
            int typeComparison = left.annotationType().getName().compareTo(right.annotationType().getName());
            if (typeComparison != 0)
            {
                return typeComparison;
            }
            return left.toString().compareTo(right.toString());
        };

        Arrays.sort(qualifiersA, comparator);
        Arrays.sort(qualifiersB, comparator);

        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, qualifiersA);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, qualifiersB);

        Assert.assertEquals(a, b);
        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
