    @Test
    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        // Compare all fields exactly, treating qualifier array as an order-insensitive, complete list.
        Field typeField = BeanCacheKey.class.getDeclaredField("type");
        typeField.setAccessible(true);
        Assert.assertEquals(typeField.get(a), typeField.get(b));

        Field pathField = BeanCacheKey.class.getDeclaredField("path");
        pathField.setAccessible(true);
        Assert.assertEquals(pathField.get(a), pathField.get(b));

        Field delegateField = BeanCacheKey.class.getDeclaredField("delegate");
        delegateField.setAccessible(true);
        Assert.assertEquals(delegateField.get(a), delegateField.get(b));

        Field qualifiersField = BeanCacheKey.class.getDeclaredField("qualifiers");
        qualifiersField.setAccessible(true);
        Annotation[] qualsA = (Annotation[]) qualifiersField.get(a);
        Annotation[] qualsB = (Annotation[]) qualifiersField.get(b);

        List<Annotation> listA = new ArrayList<>(Arrays.asList(qualsA));
        List<Annotation> listB = new ArrayList<>(Arrays.asList(qualsB));
        Comparator<Annotation> annotationComparator = Comparator
                .comparing((Annotation ann) -> ann.annotationType().getName())
                .thenComparing(Object::toString);
        listA.sort(annotationComparator);
        listB.sort(annotationComparator);
        Assert.assertEquals("Qualifiers should be equal as order-insensitive lists", listA, listB);

        Assert.assertEquals(a.hashCode(), b.hashCode());
    }
