public void transport_chunking() throws Exception {
    // Reset any static state in ClassFilter that may have been polluted by other tests.
    // Set the default ClassFilter to a clean TestFilter instance to ensure independent behavior.
    try {
        java.lang.reflect.Field defaultFilterField = ClassFilter.class.getDeclaredField("DEFAULT");
        defaultFilterField.setAccessible(true);
        defaultFilterField.set(null, new TestFilter());
    } catch (NoSuchFieldException e) {
        // If field name differs, try to set any static ClassFilter field.
        boolean set = false;
        for (java.lang.reflect.Field f : ClassFilter.class.getDeclaredFields()) {
            if (java.lang.reflect.Modifier.isStatic(f.getModifiers()) && ClassFilter.class.isAssignableFrom(f.getType())) {
                f.setAccessible(true);
                f.set(null, new TestFilter());
                set = true;
                break;
            }
        }
        if (!set) {
            throw new RuntimeException("Unable to reset ClassFilter static state", e);
        }
    }
    // Also clear any override system property
    System.clearProperty(ClassFilter.class.getName());
    setUp();
    commandStreamTestSequence();
}
