    @Test
    public void testInheritedReflectionStatics() {
        final InheritedReflectionStaticFieldsFixture instance1 = new InheritedReflectionStaticFieldsFixture();

        final java.util.function.Function<String, String> normalizeReflectionOrder = s -> {
            final int start = s.indexOf('[');
            final int end = s.lastIndexOf(']');
            if (start < 0 || end <= start) {
                throw new AssertionError("Missing reflection field brackets: " + s);
            }
            final String prefix = s.substring(0, start);
            final String body = s.substring(start + 1, end);
            if (body.isEmpty()) {
                return prefix + "[]";
            }
            final String[] entries = body.split(",");
            java.util.Arrays.sort(entries, (a, b) -> {
                final int eqA = a.indexOf('=');
                final int eqB = b.indexOf('=');
                final String keyA = eqA >= 0 ? a.substring(0, eqA) : a;
                final String keyB = eqB >= 0 ? b.substring(0, eqB) : b;
                return keyA.compareTo(keyB);
            });
            return prefix + "[" + String.join(",", entries) + "]";
        };

        assertEquals(
            normalizeReflectionOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890]"),
            normalizeReflectionOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, InheritedReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeReflectionOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeReflectionOrder.apply(ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeReflectionOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeReflectionOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
        assertEquals(
            normalizeReflectionOrder.apply(this.toBaseString(instance1) + "[staticString2=staticString2,staticInt2=67890,staticString=staticString,staticInt=12345]"),
            normalizeReflectionOrder.apply(this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class)));
    }
