    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        // ---------------------------------------------------------------------
        // Order-insensitive complete SQL structure validation
        // ---------------------------------------------------------------------
        final int columnsStart = sql.indexOf("SELECT ") + "SELECT ".length();
        final int columnsEnd = sql.indexOf("  FROM");
        Assert.assertTrue("SQL must contain 'SELECT '", columnsStart >= "SELECT ".length());
        Assert.assertTrue("SQL must contain '  FROM'", columnsEnd > columnsStart);

        final String columnsPart = sql.substring(columnsStart, columnsEnd);
        final String[] columnsArray = columnsPart.split(",");
        final Set<String> actualColumns = new TreeSet<String>();
        for (String column : columnsArray) {
            actualColumns.add(column.trim());
        }
        final Set<String> expectedColumns = new TreeSet<String>(Arrays.asList(
                "id", "user_name", "address", "state"
        ));
        Assert.assertEquals("SELECT columns set mismatch", expectedColumns, actualColumns);

        final int tableStart = columnsEnd + "  FROM ".length();
        final int tableEnd = sql.indexOf("<where>");
        Assert.assertTrue("SQL must contain '<where>'", tableEnd > tableStart);
        Assert.assertEquals("FROM table mismatch", "user",
                sql.substring(tableStart, tableEnd).trim());

        final int whereStart = tableEnd + "<where>".length();
        final int whereEnd = sql.indexOf("</where>");
        Assert.assertTrue("SQL must contain '</where>'", whereEnd > whereStart);
        final String wherePart = sql.substring(whereStart, whereEnd);

        final Set<String> actualIfBlocks = new TreeSet<String>();
        int searchFrom = 0;
        while (true) {
            final int ifStart = wherePart.indexOf("<if test=\"", searchFrom);
            if (ifStart < 0) {
                break;
            }
            final int ifEnd = wherePart.indexOf("</if>", ifStart);
            Assert.assertTrue("Malformed <if> block", ifEnd >= ifStart);
            actualIfBlocks.add(wherePart.substring(ifStart, ifEnd + "</if>".length()));
            searchFrom = ifEnd + "</if>".length();
        }

        final Set<String> expectedIfBlocks = new TreeSet<String>(Arrays.asList(
                "<if test=\"id != null\"> AND id = #{id}</if>",
                "<if test=\"userName != null\"> AND user_name = #{userName}</if>",
                "<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>",
                "<if test=\"state != null\"> AND state = #{state}</if>"
        ));
        Assert.assertEquals("WHERE if-block set mismatch", expectedIfBlocks, actualIfBlocks);

        // ---------------------------------------------------------------------
        // Result mapping assertions
        // ---------------------------------------------------------------------
        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();
        Assert.assertEquals(4, resultMappings.size());

        final Map<String, ResultMapping> resultMappingByColumn = new HashMap<String, ResultMapping>();
        for (ResultMapping resultMapping : resultMappings) {
            resultMappingByColumn.put(resultMapping.getColumn(), resultMapping);
        }
        Assert.assertEquals("Result mapping column set mismatch", 4, resultMappingByColumn.size());

        final ResultMapping idMapping = resultMappingByColumn.get("id");
        final ResultMapping userNameMapping = resultMappingByColumn.get("user_name");
        final ResultMapping addressMapping = resultMappingByColumn.get("address");
        final ResultMapping stateMapping = resultMappingByColumn.get("state");

        Assert.assertNotNull("id mapping should exist", idMapping);
        Assert.assertNotNull("userName mapping should exist", userNameMapping);
        Assert.assertNotNull("address mapping should exist", addressMapping);
        Assert.assertNotNull("state mapping should exist", stateMapping);

        Assert.assertEquals("id", idMapping.getColumn());
        Assert.assertEquals("id", idMapping.getProperty());
        Assert.assertTrue(idMapping.getFlags().contains(ResultFlag.ID));

        Assert.assertEquals("user_name", userNameMapping.getColumn());
        Assert.assertEquals("userName", userNameMapping.getProperty());

        Assert.assertEquals("address", addressMapping.getColumn());
        Assert.assertEquals("address", addressMapping.getProperty());
        Assert.assertEquals(AddressHandler.class, addressMapping.getTypeHandler().getClass());

        Assert.assertEquals("state", stateMapping.getColumn());
        Assert.assertEquals("state", stateMapping.getProperty());
        Assert.assertEquals(EnumTypeHandler.class, stateMapping.getTypeHandler().getClass());
    }
