        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String actualSql = sqlBuilder.toString();

        // Normalize the order-dependent parts of the generated SQL so the assertion
        // remains exact but stable under non-deterministic iteration order.
        Pattern sqlPattern = Pattern.compile("^SELECT (.*?)  FROM (.*?) <where>(.*?)</where>$");
        Matcher matcher = sqlPattern.matcher(actualSql);
        Assert.assertTrue("Unexpected generated SQL format: " + actualSql, matcher.matches());

        String columnsPart = matcher.group(1);
        String tablePart = matcher.group(2).trim();
        String wherePart = matcher.group(3);

        List<String> columns = new ArrayList<>();
        for (String column : columnsPart.split(",")) {
            columns.add(column.trim());
        }
        Collections.sort(columns);
        StringBuilder canonicalColumnsBuilder = new StringBuilder();
        for (int i = 0; i < columns.size(); i++) {
            if (i > 0) {
                canonicalColumnsBuilder.append(",");
            }
            canonicalColumnsBuilder.append(columns.get(i));
        }
        String canonicalColumns = canonicalColumnsBuilder.toString();

        List<String> ifBlocks = new ArrayList<>();
        int fromIndex = 0;
        int idx = wherePart.indexOf("<if test=\"", fromIndex);
        while (idx >= 0) {
            int end = wherePart.indexOf("</if>", idx);
            Assert.assertTrue("Malformed <if> block", end >= idx);
            ifBlocks.add(wherePart.substring(idx, end + "</if>".length()));
            fromIndex = end + "</if>".length();
            idx = wherePart.indexOf("<if test=\"", fromIndex);
        }
        Collections.sort(ifBlocks);
        StringBuilder canonicalWhereBuilder = new StringBuilder();
        for (String block : ifBlocks) {
            canonicalWhereBuilder.append(block);
        }
        String canonicalWhere = canonicalWhereBuilder.toString();

        String canonicalSql = "SELECT " + canonicalColumns + "  FROM " + tablePart + " <where>" + canonicalWhere + "</where>";

